<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Bouncing Ball Playground</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    background: #0a0e1a;
    color: #e2e8f0;
    font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 24px;
  }
  .wrap {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 16px;
    width: 100%;
    max-width: 640px;
  }
  h1 {
    font-size: 1.6rem;
    letter-spacing: 0.5px;
    color: #f1f5f9;
    text-shadow: 0 0 24px rgba(56,189,248,0.4);
  }
  p.hint { color: #94a3b8; font-size: 0.9rem; }
  #sim {
    width: 500px;
    height: 500px;
    min-width: 400px;
    min-height: 400px;
    max-width: 92vw;
    background: #0b1020;
    border: 1px solid #1e293b;
    border-radius: 16px;
    box-shadow: 0 0 0 1px rgba(56,189,248,0.15), 0 20px 60px rgba(0,0,0,0.6), 0 0 40px rgba(56,189,248,0.08);
    cursor: crosshair;
    display: block;
  }
  .controls { display: flex; gap: 12px; flex-wrap: wrap; justify-content: center; }
  button {
    background: #1e293b;
    color: #f1f5f9;
    border: 1px solid #334155;
    border-radius: 10px;
    padding: 10px 20px;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: transform 0.08s ease, background 0.15s ease, box-shadow 0.15s ease;
  }
  button:hover { background: #334155; box-shadow: 0 0 16px rgba(56,189,248,0.3); }
  button:active { transform: scale(0.95); }
  #drop { background: #0284c7; border-color: #38bdf8; }
  #drop:hover { background: #0ea5e9; }
  #play { background: #16a34a; border-color: #4ade80; }
  #play:hover { background: #22c55e; }
  #play.paused { background: #ca8a04; border-color: #facc15; }
  .counter { color: #64748b; font-size: 0.85rem; }
</style>
</head>
<body>
<div class="wrap">
  <h1>⚽ Bouncing Ball Playground</h1>
  <p class="hint">Click the canvas to add balls • Gravity + wall bounces</p>
  <canvas id="sim" width="500" height="500"></canvas>
  <div class="controls">
    <button id="drop">Drop Ball</button>
    <button id="play">Pause</button>
    <button id="clear">Clear</button>
  </div>
  <div class="counter" id="count">0 balls</div>
</div>
<script>
(function() {
  var canvas = document.getElementById('sim');
  var ctx = canvas.getContext('2d');
  var W = canvas.width;
  var H = canvas.height;
  var GRAVITY = 0.5;
  var RESTITUTION = 0.85;

  var ballsArray = [];
  var hueCounter = 0;

  function randomColor() {
    hueCounter = (hueCounter + 47) % 360;
    var h = Math.floor(Math.random() * 360);
    // mix deterministic + random for variety
    var hue = (h + hueCounter) % 360;
    return 'hsl(' + hue + ', 90%, 60%)';
  }

  function clampBallToBounds(b) {
    if (b.x - b.r < 0) { b.x = b.r; }
    if (b.x + b.r > W) { b.x = W - b.r; }
    if (b.y - b.r < 0) { b.y = b.r; }
    if (b.y + b.r > H) { b.y = H - b.r; }
    // handle case where radius larger than canvas
    if (b.r * 2 > W) { b.x = W / 2; }
    if (b.r * 2 > H) { b.y = H / 2; }
  }

  function addBall(x, y, vx, vy, r) {
    if (typeof x !== 'number' || isNaN(x)) x = W / 2;
    if (typeof y !== 'number' || isNaN(y)) y = 50;
    if (typeof vx !== 'number' || isNaN(vx)) vx = 0;
    if (typeof vy !== 'number' || isNaN(vy)) vy = 0;
    if (typeof r !== 'number' || isNaN(r) || r <= 0) r = 15;
    // clamp radius to fit
    if (r * 2 > W) r = Math.floor(W / 4);
    if (r * 2 > H) r = Math.floor(H / 4);
    if (r < 3) r = 3;
    var b = { x: x, y: y, vx: vx, vy: vy, r: r, color: randomColor() };
    clampBallToBounds(b);
    ballsArray.push(b);
    draw();
    updateCount();
    return b;
  }

  function clear() {
    ballsArray.length = 0;
    draw();
    updateCount();
  }

  function balls() {
    return ballsArray.map(function(b) {
      return { x: b.x, y: b.y, vx: b.vx, vy: b.vy, r: b.r, color: b.color };
    });
  }

  function step(dt) {
    if (typeof dt !== 'number' || isNaN(dt) || dt <= 0) dt = 1;
    // cap dt to avoid insane jumps while still staying in bounds
    if (dt > 5) dt = 5;
    for (var i = 0; i < ballsArray.length; i++) {
      var b = ballsArray[i];
      // gravity
      b.vy += GRAVITY * dt;
      // integrate
      b.x += b.vx * dt;
      b.y += b.vy * dt;
      // bounce off edges with clamp (prevents tunneling)
      if (b.x - b.r < 0) {
        b.x = b.r;
        b.vx = -b.vx * RESTITUTION;
      } else if (b.x + b.r > W) {
        b.x = W - b.r;
        b.vx = -b.vx * RESTITUTION;
      }
      if (b.y - b.r < 0) {
        b.y = b.r;
        b.vy = -b.vy * RESTITUTION;
      } else if (b.y + b.r > H) {
        b.y = H - b.r;
        b.vy = -b.vy * RESTITUTION;
      }
      // final safety clamp
      if (b.x - b.r < 0) b.x = b.r;
      if (b.x + b.r > W) b.x = W - b.r;
      if (b.y - b.r < 0) b.y = b.r;
      if (b.y + b.r > H) b.y = H - b.r;
    }
    draw();
    updateCount();
  }

  function draw() {
    ctx.fillStyle = '#0b1020';
    ctx.fillRect(0, 0, W, H);
    // subtle grid
    ctx.strokeStyle = 'rgba(148,163,184,0.07)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (var gx = 50; gx < W; gx += 50) { ctx.moveTo(gx, 0); ctx.lineTo(gx, H); }
    for (var gy = 50; gy < H; gy += 50) { ctx.moveTo(0, gy); ctx.lineTo(W, gy); }
    ctx.stroke();
    for (var i = 0; i < ballsArray.length; i++) {
      var b = ballsArray[i];
      ctx.save();
      ctx.shadowColor = b.color;
      ctx.shadowBlur = 18;
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
      ctx.fillStyle = b.color;
      ctx.fill();
      ctx.shadowBlur = 0;
      // highlight for juicy look
      ctx.beginPath();
      ctx.arc(b.x - b.r * 0.3, b.y - b.r * 0.3, b.r * 0.35, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255,255,255,0.55)';
      ctx.fill();
      ctx.lineWidth = 2;
      ctx.strokeStyle = 'rgba(255,255,255,0.35)';
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
      ctx.stroke();
      ctx.restore();
    }
  }

  function updateCount() {
    var el = document.getElementById('count');
    if (el) el.textContent = ballsArray.length + (ballsArray.length === 1 ? ' ball' : ' balls');
  }

  window.sim = {
    w: W,
    h: H,
    balls: balls,
    addBall: addBall,
    clear: clear,
    step: step
  };

  // UI wiring
  var playing = true;
  var playBtn = document.getElementById('play');
  var dropBtn = document.getElementById('drop');
  var clearBtn = document.getElementById('clear');

  function setPlaying(v) {
    playing = v;
    if (playBtn) {
      playBtn.textContent = playing ? 'Pause' : 'Play';
      if (playing) playBtn.classList.remove('paused');
      else playBtn.classList.add('paused');
    }
  }

  if (playBtn) {
    playBtn.addEventListener('click', function() { setPlaying(!playing); });
  }
  if (dropBtn) {
    dropBtn.addEventListener('click', function() {
      var r = 10 + Math.random() * 12;
      var x = r + Math.random() * (W - r * 2);
      var vx = (Math.random() - 0.5) * 6;
      addBall(x, 40 + Math.random() * 30, vx, 0, r);
    });
  }
  if (clearBtn) {
    clearBtn.addEventListener('click', function() { clear(); });
  }

  function canvasPoint(e) {
    var rect = canvas.getBoundingClientRect();
    var sx = canvas.width / rect.width;
    var sy = canvas.height / rect.height;
    return {
      x: (e.clientX - rect.left) * sx,
      y: (e.clientY - rect.top) * sy
    };
  }

  canvas.addEventListener('pointerdown', function(e) {
    var p = canvasPoint(e);
    var r = 10 + Math.random() * 12;
    var vx = (Math.random() - 0.5) * 8;
    var vy = -Math.random() * 4;
    addBall(p.x, p.y, vx, vy, r);
  });

  // animation loop
  function loop() {
    if (playing) step(1);
    requestAnimationFrame(loop);
  }

  // seed a few balls for immediate delight
  addBall(W * 0.3, 80, 2, 0, 16);
  addBall(W * 0.7, 140, -2.5, 0, 13);
  addBall(W * 0.5, 60, 1, 0, 19);
  draw();
  setPlaying(true);
  requestAnimationFrame(loop);
})();
</script>
</body>
</html>
```
